# Let's verify K_{3,12} on vertices 0..14
edges = []
A = [0,1,2]
B = list(range(3,15))
for a in A:
    for b in B:
        edges.append((a,b))

print("Number of edges:", len(edges))

# Check degrees
degrees = [0]*15
for u,v in edges:
    degrees[u] += 1
    degrees[v] += 1
print("Degrees:", degrees)
print("Min degree:", min(degrees))

# Check clique size (simple brute force)
from itertools import combinations
# Build adjacency set
adj = [set() for _ in range(15)]
for u,v in edges:
    adj[u].add(v)
    adj[v].add(u)

max_clique = 0
for r in range(1, 16):
    found = False
    for subset in combinations(range(15), r):
        ok = True
        for i in range(r):
            for j in range(i+1, r):
                if subset[j] not in adj[subset[i]]:
                    ok = False
                    break
            if not ok:
                break
        if ok:
            found = True
            max_clique = r
    if not found:
        break
print("Max clique size:", max_clique)

# Check chromatic number (greedy coloring as lower/upper bound, but for bipartite it's 2)
# BFS to check bipartite
color = [-1]*15
from collections import deque
is_bipartite = True
for start in range(15):
    if color[start] == -1:
        color[start] = 0
        q = deque([start])
        while q:
            u = q.popleft()
            for v in adj[u]:
                if color[v] == -1:
                    color[v] = 1 - color[u]
                    q.append(v)
                elif color[v] == color[u]:
                    is_bipartite = False
                    break
            if not is_bipartite:
                break
    if not is_bipartite:
        break
print("Is bipartite:", is_bipartite)
print("Chromatic number:", 2 if is_bipartite else ">2")
